public static int searchInsert(int[] nums, int target) {
    int low = 0;                          // left edge of the search range
    int high = nums.length;               // exclusive right edge
    while (low < high) {                  // narrow the first value >= target
        int mid = low + (high - low) / 2; // overflow-safe midpoint
        if (nums[mid] < target) low = mid + 1; // discard the smaller prefix
        else high = mid;                  // retain this possible boundary
    }
    return low;                           // target index or insertion position
}

