int searchInsert(vector<int>& nums, int target) {
    int low = 0;                          // left edge of the search range
    int high = nums.size();               // exclusive right edge
    while (low < high) {                  // search for the first value >= target
        int mid = low + (high - low) / 2; // overflow-safe midpoint
        if (nums[mid] < target) low = mid + 1; // answer is to the right
        else high = mid;                  // keep mid and search left
    }
    return low;                           // target index or insertion position
}
